<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { usePlatform } from '../stores/platform'
import { duties, reviewDuties, has, type Duty } from '../domain/identity'
import type { Plan,Question } from '../domain/types'
import { professions } from '../mocks/seed'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
import QuestionEditor from '../components/QuestionEditor.vue'
const s=usePlatform(),route=useRoute(),router=useRouter();const page=computed(()=>String(route.params.page));const search=ref(''),filter=ref('全部'),planModal=ref(false),selected=ref<Question|null>(null),note=ref(''),reviewStage=ref('待初审'),expertDetail=ref<string|null>(null)
const titles:Record<string,[string,string]>={plans:['命题计划','从计划发布到专家协作，有序推进理论与技能题库建设。'],tasks:['我的命题任务','聚焦分配给您的命题任务，及时完成提交与修改。'],experts:['专家管理','汇集命题、审题与考评资源，按专业与任务进行授权。'],reviews:['审核与入库','初审、复审、终审逐级把关，保留每一轮意见与版本。'],editor:['在线命题','使用标准化字段开发试题，支持理论与技能多类题型。'],history:['历史与协作','查看试题版本、审核意见与全生命周期操作轨迹。']}
const editingPlanId=ref('')
const grantPerson=ref(''),grantDuties=ref<Duty[]>([]),grantEnabled=ref(true)
function openGrant(id:string){const p=s.people.find(p=>p.id===id)!;grantPerson.value=id;grantDuties.value=[...p.duties];grantEnabled.value=p.enabled}
const stages=computed(()=>Object.keys(reviewDuties).filter(st=>s.can(reviewDuties[st]!)))
reviewStage.value=stages.value[0]||'待初审'
const currentTitle=computed(()=>titles[page.value]||titles.plans!)
const form=ref<Omit<Plan,'id'>>({name:'',profession:professions[0]!,level:'三级 / 高级工',kind:'理论',target:20,expert:'张明',deadline:'2026-10-15',status:'待发布',description:'',leadId:'lead',reviewers:{'待初审':'initial','待复审':'second','待终审':'final','待入库':'lead'}})
const plans=computed(()=>s.data.plans.filter(p=>(s.can('development')||p.expert===s.actor||s.can('lead')&&p.leadId===s.personId)&&(!search.value||p.name.includes(search.value))&&(filter.value==='全部'||p.status===filter.value)))
const reviews=computed(()=>s.data.questions.filter(q=>s.canReview(q)&&q.status===reviewStage.value&&(!search.value||q.title.includes(search.value)||q.id.includes(search.value))))
const myQuestions=computed(()=>s.data.questions.filter(q=>s.canReadQuestion(q)&&q.author===s.actor&&q.status!=='已入库'))
const editing=computed(()=>s.data.questions.find(q=>q.id===route.query.id))
const experts=computed(()=>s.data.experts.filter(e=>!search.value||e.name.includes(search.value)||e.profession.includes(search.value)))
const history=computed(()=>s.data.questions.filter(q=>s.canReadQuestion(q)).filter(q=>q.history.length>1||q.status!=='已入库').filter(q=>!search.value||q.title.includes(search.value)))
function savePlan(){s.run(()=>{s.savePlan(form.value,editingPlanId.value||undefined);planModal.value=false})}
function openReview(q:Question){selected.value=q;note.value=''}
function review(approve:boolean){s.run(()=>{s.reviewQuestion(selected.value!.id,approve,note.value,selected.value!.status);selected.value=null})}
watch(()=>route.query.id,()=>{})
</script>
<template>
  <PageHead :title="currentTitle[0]" :subtitle="currentTitle[1]" eyebrow="题库建设 / 命题协作"><RouterLink v-if="page==='plans'" class="button" to="/protocol/development">命题质量统计</RouterLink><button v-if="page==='plans'&&s.can('development')" class="button primary" @click="editingPlanId='';form.name='';form.status='待发布';planModal=true"><Icon name="Plus" :size="17"/>新建命题计划</button><button v-if="(page==='tasks'||page==='history')&&s.can('author')" class="button primary" @click="router.push('/authoring/editor')"><Icon name="PenLine" :size="17"/>新建试题</button></PageHead>
  <template v-if="page==='plans'||page==='tasks'">
    <div class="mini-metrics"><div><span>计划总数</span><strong>{{plans.length}} <small>项</small></strong></div><div><span>进行中</span><strong>{{plans.filter(p=>p.status==='进行中').length}} <small>项</small></strong></div><div><span>计划开发题量</span><strong>{{plans.reduce((a,p)=>a+p.target,0)}} <small>道</small></strong></div><div><span>已关联试题</span><strong>{{s.data.questions.filter(q=>q.taskId).length}} <small>道</small></strong></div></div>
    <section class="panel"><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="17"/><input v-model="search" placeholder="搜索计划名称…"/></div><select v-model="filter"><option>全部</option><option>进行中</option><option>待发布</option></select><span class="filter-meta">共 {{plans.length}} 项计划</span></div><div class="table-scroll"><table><thead><tr><th>命题计划</th><th>工种 / 等级</th><th>类型</th><th>命题专家 / 负责人</th><th>开发进度</th><th>截止日期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in plans" :key="p.id"><td><strong class="cell-title">{{p.name}}</strong><small>{{p.id}}</small></td><td>{{p.profession}}<small>{{p.level}}</small></td><td>{{p.kind}}</td><td><span class="inline-avatar">{{p.expert[0]}}</span>{{p.expert}}<small>负责：{{s.people.find(u=>u.id===p.leadId)?.name}}</small></td><td><div class="progress-track"><i :style="{width:Math.min(100,s.data.questions.filter(q=>q.taskId===p.id).length/p.target*100)+'%'}"></i></div><small>{{s.data.questions.filter(q=>q.taskId===p.id).length}} / {{p.target}} 道</small></td><td>{{p.deadline}}</td><td><Badge :text="p.status"/></td><td><button v-if="s.can('development')" class="text-button" @click="editingPlanId=p.id;form=JSON.parse(JSON.stringify(p));planModal=true">任务分工</button><button v-if="s.can('development')&&p.status==='待发布'" class="text-button" @click="s.run(()=>s.publishPlan(p.id))">发布任务</button><button v-else class="text-button" @click="s.can('author')&&p.expert===s.actor?router.push({path:'/authoring/editor',query:{task:p.id}}):s.notify(p.description)">{{s.can('author')&&p.expert===s.actor?'开始命题':'计划说明'}}</button></td></tr></tbody></table></div><Empty v-if="!plans.length"/></section>
    <section v-if="page==='tasks'" class="panel spaced"><div class="panel-head"><h3>我的草稿与待处理试题</h3><span class="subtle-label">{{myQuestions.length}} 道</span></div><div class="table-scroll"><table><thead><tr><th>试题</th><th>题型</th><th>版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="q in myQuestions"><td>{{q.title}}<small>{{q.id}}</small></td><td>{{q.type}}</td><td>V{{q.version}}</td><td><Badge :text="q.status"/></td><td><button v-if="['草稿','已退回'].includes(q.status)" class="text-button" @click="router.push({path:'/authoring/editor',query:{id:q.id}})">继续编辑</button><button v-else class="text-button" @click="selected=q">查看轨迹</button></td></tr></tbody></table></div></section>
  </template>
  <template v-if="page==='experts'"><div class="notice">职责授权立即影响演示人员的菜单、任务和操作。以下为演示分工，兼任及特批规则以甲方制度为准。</div><div class="expert-grid spaced"><article v-for="p in s.people.filter(p=>['expert','marker'].includes(p.role))" :key="p.id" class="panel expert-card"><h3>{{p.name}}</h3><p>{{p.org}} · {{p.kinds.join(' / ')}}</p><Badge :text="p.enabled?'已授权':'已停用'"/><div class="tag-list"><span v-for="d in p.duties">{{duties[d]}}</span></div><button class="button" @click="openGrant(p.id)">维护职责授权</button></article></div></template>
  <Modal v-if="grantPerson" title="维护专家职责授权" @close="grantPerson=''"><label class="field">状态<select v-model="grantEnabled"><option :value="true">已授权</option><option :value="false">已停用</option></select></label><div class="grant-grid"><label v-for="d in (['lead','author','initial','second','final','intake','assemble','review','arbitrate','skill','learn'] as Duty[])"><input type="checkbox" v-model="grantDuties" :value="d"/>{{duties[d]}}</label></div><template #footer><button class="button primary" @click="s.run(()=>{s.savePerson(grantPerson,grantDuties,grantEnabled);grantPerson=''})">保存授权</button></template></Modal>
  <template v-if="page==='reviews'"><div class="workflow-bar"><div v-for="(stage,i) in ['命题提交','初审','复审','终审','入库']" :class="{current:reviewStage.includes(stage)}"><span>{{i+1}}</span>{{stage}}<Icon v-if="i<4" name="ChevronRight" :size="16"/></div></div><section class="panel"><div class="tabs"><button v-for="stage in stages" :class="{active:reviewStage===stage}" @click="reviewStage=stage">{{stage}} <span>{{s.data.questions.filter(q=>s.canReview(q)&&q.status===stage).length}}</span></button></div><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="17"/><input v-model="search" placeholder="搜索题干或题号…"/></div><span class="filter-meta">仅显示分配给当前人员的任务 · 处理后交接下一节点</span></div><div class="table-scroll"><table><thead><tr><th>试题内容</th><th>题型 / 分类</th><th>知识点</th><th>命题专家</th><th>版本</th><th>当前阶段</th><th>操作</th></tr></thead><tbody><tr v-for="q in reviews"><td><strong class="cell-title">{{q.title}}</strong><small>{{q.id}}</small></td><td>{{q.type}}<small>{{q.bank}}</small></td><td>{{q.knowledge}}</td><td>{{q.author}}</td><td>V{{q.version}}</td><td><Badge :text="q.status"/></td><td><button class="text-button" @click="openReview(q)">{{q.status==='待入库'?'确认入库':'开始审核'}} <Icon name="ArrowRight" :size="14"/></button></td></tr></tbody></table></div><Empty v-if="!reviews.length" title="当前阶段没有待处理试题" description="切换其他阶段，或从在线命题提交新的试题。"/></section></template>
  <div v-if="page==='editor'&&(!editing||s.canEditQuestion(editing))" class="editor-layout"><section class="panel editor-panel"><QuestionEditor :key="String(route.query.id||route.query.task||'new')" :question="editing" :task-id="String(route.query.task||'')" @saved="(id:string)=>router.replace({path:'/authoring/editor',query:{id}})"/></section><aside class="editor-aside"><section class="panel"><div class="panel-head"><h3>命题规范提示</h3><Icon name="Lightbulb" :size="18"/></div><div class="aside-copy"><h4>题目结构完整</h4><p>明确题型、知识点、题干、答案和解析，技能题需补充准备要求与评分表。</p><h4>审核过程可溯</h4><p>提交后按初审、复审、终审流转。审核中不可直接修改，退回后重新提交。</p><h4>历史版本独立</h4><p>修订创建新的题目版本，已冻结试卷保留原始题面和答案。</p></div></section><section class="panel spaced"><div class="panel-head"><h3>版本与意见</h3></div><div class="timeline compact"><div v-for="h in editing?.history.slice().reverse()"><i></i><strong>{{h.action}} · V{{h.version}}</strong><p>{{h.note}}</p><small>{{h.actor}} · {{h.time}}</small></div><p v-if="!editing" class="muted">保存试题后生成版本记录。</p></div></section></aside></div>
  <Empty v-if="page==='editor'&&editing&&!s.canEditQuestion(editing)" title="此试题不在您的编辑范围"/><section v-if="page==='history'" class="panel"><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="17"/><input v-model="search" placeholder="搜索历史试题…"/></div></div><div v-for="q in history" class="history-row"><div><strong>{{q.title}}</strong><p>{{q.id}} · V{{q.version}} · {{q.history.length}}条过程记录</p></div><Badge :text="q.status"/><button class="button small" @click="selected=q">查看版本与意见</button></div><Empty v-if="!history.length"/></section>
  <Modal v-if="planModal" :title="editingPlanId?'命题计划与任务分工':'新建命题计划'" wide @close="planModal=false"><div class="form-grid"><label class="span-two">计划名称 <b>*</b><input v-model="form.name" placeholder="如：2026年装配工理论题库专项开发"/></label><label>职业工种<select v-model="form.profession"><option v-for="p in professions">{{p}}</option></select></label><label>技能等级<select v-model="form.level"><option>三级 / 高级工</option><option>四级 / 中级工</option></select></label><label>开发类型<select v-model="form.kind"><option>理论</option><option>技能</option></select></label><label>计划题量<input v-model.number="form.target" type="number" min="1"/></label><label>命题专家<select v-model="form.expert"><option v-for="e in s.people.filter(u=>has(u,'author')&&u.kinds.includes(form.kind))">{{e.name}}</option></select></label><label>命题负责人<select v-model="form.leadId"><option v-for="u in s.people.filter(u=>has(u,'lead'))" :value="u.id">{{u.name}}</option></select></label><label v-for="(d,stage) in reviewDuties">{{stage}}处理人<select v-model="form.reviewers![stage]"><option v-for="u in s.people.filter(u=>has(u,d)&&u.kinds.includes(form.kind))" :value="u.id">{{u.name}}</option></select></label><label>截止日期<input v-model="form.deadline" type="date"/></label><label class="span-two">任务要求<textarea v-model="form.description" rows="3"/></label></div><template #footer><button class="button" @click="planModal=false">取消</button><button class="button primary" @click="savePlan">保存计划</button></template></Modal>
  <Modal v-if="selected" :title="page==='reviews'?'试题审核 · '+selected.id:'试题版本与协作记录'" wide @close="selected=null"><div class="tag-list"><Badge :text="selected.status"/><span>{{selected.type}}</span><span>{{selected.knowledge}}</span><span>V{{selected.version}}</span></div><h3 class="detail-title">{{selected.title}}</h3><div v-for="(o,i) in selected.options" class="preview-option" :class="{correct:selected.answers.includes(String(i))}">{{String.fromCharCode(65+i)}}. {{o}}<Icon v-if="selected.answers.includes(String(i))" name="CircleCheck" :size="17"/></div><div class="notice"><strong>参考解析：</strong>{{selected.analysis}}</div><div v-if="selected.rubric.length" class="rubric-list"><p v-for="r in selected.rubric">{{r.label}}<strong>{{r.max}}分</strong></p></div><h4>任务交接人员</h4><div class="tag-list"><span v-for="(id,stage) in selected.assignments">{{stage}}：{{s.people.find(p=>p.id===id)?.name}}</span></div><h4>审核与版本轨迹</h4><div class="timeline compact"><div v-for="h in selected.history.slice().reverse()"><i></i><strong>{{h.action}} · V{{h.version}}</strong><p>{{h.note}}</p><small>{{h.actor}} · {{h.time}}</small></div></div><label v-if="page==='reviews'" class="field">审核意见<textarea v-model="note" rows="3" placeholder="通过意见可选，退回时请说明需要修改的内容…"/></label><template v-if="page==='reviews'" #footer><button class="button danger-outline" @click="review(false)"><Icon name="Undo2" :size="16"/>退回修改</button><button class="button primary" @click="review(true)"><Icon name="Check" :size="16"/>{{selected.status==='待入库'?'确认入库':'审核通过'}}</button></template></Modal>
  <Modal v-if="expertDetail" title="专家档案与授权" @close="expertDetail=null"><template v-for="e in s.data.experts.filter(e=>e.id===expertDetail)"><div class="profile-summary"><span class="avatar large">{{e.name[0]}}</span><div><h3>{{e.name}}</h3><p>{{e.org}} · {{e.profession}}</p></div></div><label class="field">授权职责<input v-model="e.role"/></label><label class="field">授权状态<select v-model="e.status"><option>已授权</option><option>已停用</option></select></label><div class="notice">本页面维护合成专家档案。具体数据范围和回避规则待甲方确认，正式权限需服务端实施。</div><button class="button primary" @click="s.audit('专家管理','修改授权',e.name);s.notify('专家授权配置已保存');expertDetail=null">保存授权</button></template></Modal>
</template>
